DECLARE @skills NVARCHAR(MAX) = N'{{ JSON.stringify($json.required_skills).replace(/'/g, "''") }}';

INSERT INTO jobs (job_title, company, experience_years_min, experience_years_max, seniority, language_required, submitted_at)
VALUES (
  N'{{ $json.job_title.replace(/'/g, "''") }}',
  N'{{ $json.company.replace(/'/g, "''") }}',
  {{ Number($json.experience_years_min) || 0 }},
  {{ Number($json.experience_years_max) || 0 }},
  N'{{ $json.seniority.replace(/'/g, "''") }}',
  N'{{ $json.language_required.replace(/'/g, "''") }}',
  CAST(CAST('{{ $json.submitted_at }}' AS DATETIMEOFFSET) AS DATETIME2)
);

DECLARE @job_id INT = SCOPE_IDENTITY();

INSERT INTO job_skills (job_id, skill)
SELECT @job_id, value FROM OPENJSON(@skills);

SELECT @job_id AS job_id;
